/** A22-R00-SALDOS: header o detalle según A22-R00-TIPO-REG (COMP). */
public sealed interface SaldoSdosRecord permits SaldoSdosRecord.Header, SaldoSdosRecord.Saldo,
        SaldoSdosRecord.Otro {

    int tipoReg();                       // 81 = saldo, 83 = fin de lógica en secuencia 1

    record Header(int tipoReg, int sistema, int producto, LocalDate fecha) implements SaldoSdosRecord {}

    /** A22-R01-REG-SAL. A22-R01-CTA 9(20) se parte en sucursal 9(4) y contrato 9(16). */
    record Saldo(int tipoReg, int sistema, int producto, int instrumento,
                 String sucursal, String contrato,          // String: conserva ceros a la izquierda
                 int edoCta, LocalDate fecPro, LocalDate fecIni, LocalDate fecFin,
                 LocalDate fecUltMov, int status,
                 List<ClaveImporte> importes,               // OCCURS 30 TIMES
                 DatosS500 s500)                            // vista A22-R01-S500 del FILXAPL X(51)
            implements SaldoSdosRecord {

        /** Primer importe con la clave indicada; P167 usa 2 (saldo actual) y 354 (disponible). */
        Optional<BigDecimal> importe(int cveSdo) {
            return importes.stream().filter(c -> c.cveSdo() == cveSdo)
                           .map(ClaveImporte::importe).findFirst();
        }
    }

    /** A22-R01-CVESDO 9(04) COMP + A22-R01-IMPT S9(13)V99 COMP: importe con signo, escala 2. */
    record ClaveImporte(int cveSdo, BigDecimal importe) {}

    /** Solo los campos de la vista S500 que P167 usa para decidir el envío a Citi. */
    record DatosS500(int moneda, int indEnvCtd) {}

    record Otro(int tipoReg, byte[] raw) implements SaldoSdosRecord {}
}

/** R04-SDOSCBII-T: layout ACC CBII de Citi (360 bytes) más el contrato interno. */
public record AcciRecord(
        String recordType,          // X(03) "ACI"
        int branch,                 // 9(03) 484
        long genCust,               // 9(11) número base del cliente
        int ccyCode,                // 9(03) 126 USD, 000 MXN
        long acctNbr,               // 9(11)
        long liaNbr,                // 9(11)
        String swiftCcy,            // X(04)
        String shortName,           // X(32)
        char statInd,               // X(01) ' ', 'B', 'C'
        int catCode,                // 9(07)
        int lastTxnDate,            // 9(07): formato no documentado en el fuente
        SignedAmount acctBal,       // 9(15)V99 + X(01)
        SignedAmount lcyAcctBal,    // 9(15)V99 + X(01)
        SignedAmount dispValBal,    // 9(15)V99 + X(01)
        String contrato) {          // ACCI-CONTRATO-T 9(16), String para conservar ceros

    /** El importe viaja como magnitud y el signo como carácter aparte. */
    public record SignedAmount(BigDecimal magnitud, char signo) {
        public static SignedAmount of(BigDecimal v) {
            return new SignedAmount(v.abs().setScale(2, RoundingMode.UNNECESSARY),
                                    v.signum() < 0 ? '-' : '+');
        }
        public BigDecimal valor() { return signo == '-' ? magnitud.negate() : magnitud; }
    }
}

@Configuration
@EnableConfigurationProperties(P167Properties.class)
public class SaldosContratoJobConfig {

    /** WKS-PARAMETRO: secuencia 9(02) + sistema 9(03). */
    @Bean
    Job saldosPorContrato(JobRepository repo, Step fechaProceso, Step resuelveLibrerias,
                          Step saldosS050, Step interfazCitiTemporal, Step completaCiti,
                          Step enviaAcc, Step trailerReporte) {
        JobExecutionDecider porSecuencia = (job, step) -> new FlowExecutionStatus(
                "SEC" + job.getJobParameters().getLong("secuencia"));

        return new JobBuilder("S151P167", repo)
                .start(fechaProceso)              // 000-005-CHECA-LIBCONTROL
                .next(resuelveLibrerias)          // DAME_TIT IN CTLVER
                .next(porSecuencia)
                    .on("SEC1").to(interfazCitiTemporal).next(completaCiti).next(enviaAcc)
                .from(porSecuencia)
                    .on("SEC2").to(saldosS050)
                .from(porSecuencia).on("*").to(trailerReporte)
                .end()
                .build();
    }
}

@Component
@RequiredArgsConstructor
class FechaProcesoTasklet implements Tasklet {
    private final LibControlClient libControl;   // CONSISDIA IN LIB-CONTROL

    @Override
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var job = ctx.getStepContext().getStepExecution().getJobExecution();
        var ctl = libControl.consultaSistemaDia(job.getJobParameters().getLong("sistema"))
                .orElseThrow(() -> new ProcesoAbortadoException(
                        "ERROR AL CONSULTAR LIB-CONTROL"));      // SET MYSELF(STATUS) TO -1
        // TASKVALUE distinto de cero sustituye la fecha de LIB-CONTROL (reproceso manual).
        Long override = job.getJobParameters().getLong("taskValue", 0L);
        LocalDate fecha = override != 0 ? Fechas.aaaammdd(override) : ctl.fechaProceso();
        job.getExecutionContext().put("fechaProceso", fecha);
        return RepeatStatus.FINISHED;
    }
}

@Component
@StepScope
public class HeaderSdosValidator implements StepExecutionListener {

    @Value("#{jobExecutionContext['fechaProceso']}") private LocalDate fechaProceso;

    /**
     * 150-007-VALIDA-HEADER. En el mainframe un header erróneo detiene la tarea con STOP
     * y espera a que el operador copie el archivo correcto; al continuar, el PERFORM UNTIL
     * vuelve a abrir y leer. Aquí el step falla y el reinicio del job hace el mismo papel.
     */
    public void valida(HeaderSdos h) {
        if (h == null) {
            throw new ArchivoVacioException("ERROR: ARCHIVO VACIO");
        }
        if (!"HD".equals(h.tipoReg()) || !h.fecha().equals(fechaProceso)) {
            throw new HeaderInvalidoException(
                "FECHA EN HEADER ERRONEA = %s FECHA CORRECTA = %s FAVOR DE COPIAR ARCHIVO CORRECTO"
                    .formatted(h.fecha(), fechaProceso));
        }
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class RuteoSaldosProcessor implements ItemProcessor<SaldoSdosRecord, Ruteado> {

    @Value("#{jobParameters['secuencia']}") private int secuencia;

    @Override
    public Ruteado process(SaldoSdosRecord rec) {
        if (!(rec instanceof SaldoSdosRecord.Saldo s) || s.tipoReg() != 81) {
            return null;                          // solo los tipo 81 producen salida
        }
        if (secuencia == 1) {
            return enviaACiti(s) ? new Ruteado(Destino.CITI, s) : null;
        }
        if (secuencia == 2) {
            boolean cuentaMaestra = s.producto() == 66
                    || (s.producto() == 500 && s.instrumento() == 1);
            if (cuentaMaestra)        return new Ruteado(Destino.SDO0066, s);
            if (s.producto() != 500)  return new Ruteado(Destino.SDO0001, s);   // 150-040
            return null;              // producto 500 con instrumento distinto de 1: se descarta
        }
        return null;
    }

    /** Precedencia literal del IF de las líneas 7132-7137: cheques 11-15 O indicador 1/2. */
    private static boolean enviaACiti(SaldoSdosRecord.Saldo s) {
        boolean chequesInstr11a15 = s.producto() == 1 && s.instrumento() > 10 && s.instrumento() < 16;
        boolean indicador = s.s500().indEnvCtd() == 1 || s.s500().indEnvCtd() == 2;
        return chequesInstr11a15 || indicador;
    }
}
